package com.example.practice;

/**
 * Polled every few seconds with a TransactionManager's head and tail (getHead(), getTail()), and
 * the time of the poll. Names a transaction that has stopped finishing, so that someone is paged
 * before the server runs out of sessions.
 */
public class StuckWatch {
    /** No transaction on this server legitimately takes longer than this. */
    private final long limitMillis;
    private long watchedTail = -1;
    private long since;

    public StuckWatch(long limitMillis) {
        this.limitMillis = limitMillis;
    }

    /** The id of a transaction that has been running for longer than the limit, or -1. */
    public long poll(long head, long tail, long nowMillis) {
        if (tail >= head) {                                 // nothing unfinished
            watchedTail = -1;
            return -1;
        }
        if (tail != watchedTail) {                          // a new oldest transaction
            watchedTail = tail;
            since = nowMillis;
        }
        return nowMillis - since > limitMillis ? tail : -1;
    }
}

import com.example.practice.StuckWatch;

import java.util.logging.ConsoleHandler;
import java.util.logging.Level;
import java.util.logging.Logger;

/** Run executes this file. Change the calls in main and see what prints. Submit grades. */
public class TryIt {
    /** Held here, so the JDK's own exit notice stays off: a logger nothing holds can be dropped. */
    private static final Logger JDK_EXIT = Logger.getLogger("java.lang.Runtime");

    public static void main(String[] args) {
        // Turn the logger up, so the log lines of your code show under the printed lines.
        System.setProperty("java.util.logging.SimpleFormatter.format", "%4$s %5$s%n");
        // Only this handler prints, and it leaves out the JDK's own detail.
        Logger root = Logger.getLogger("");
        for (java.util.logging.Handler before : root.getHandlers()) {
            root.removeHandler(before);
        }
        ConsoleHandler handler = new ConsoleHandler();
        handler.setLevel(Level.ALL);
        handler.setFilter(entry -> !String.valueOf(entry.getLoggerName()).matches("(java|javax|jdk|sun|com\\.sun)\\..*"));
        root.setLevel(Level.ALL);
        root.addHandler(handler);
        JDK_EXIT.setLevel(Level.OFF);

        // A stand-in for the collaborator, like the one the tests use for the first main case.
        try {
            StuckWatch night = new StuckWatch(20_000);
            System.out.println("night, idle at 0 s: " + night.poll(97, 97, 0));
            System.out.println("night, idle at 60 s: " + night.poll(97, 97, 60_000));
            System.out.println("night, 97 running at 75 s: " + night.poll(98, 97, 75_000));
            System.out.println("night, 97 still running at 100 s: " + night.poll(98, 97, 100_000));
            StuckWatch lunch = new StuckWatch(20_000);
            long[][] polls = { { 1520, 1511 }, { 1534, 1522 }, { 1549, 1530 }, { 1561, 1544 } };
            for (int i = 0; i < polls.length; i++)
                System.out.println("lunch, poll at " + i * 15 + " s: " + lunch.poll(polls[i][0], polls[i][1], i * 15_000L));
        } catch (RuntimeException stopped) {
            // A method you have not finished, or a bug, stops here with its message, not a build error.
            System.out.println("Run stopped: " + stopped);
        }
    }
}

